const result = await browserjs(tabId, async () => {
  // We have 250 movies. Let's fetch them from chart/top or list
  const res = await fetch('https://www.imdb.com/chart/top/');
  const html = await res.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  const items = Array.from(doc.querySelectorAll('.ipc-metadata-list-summary-item'));
  const movies = items.map((item, idx) => {
    const titleEl = item.querySelector('h3, .ipc-title__text');
    const linkEl = item.querySelector('a.ipc-title-link-wrapper, a[href*="/title/"]');
    const match = linkEl?.href?.match(/tt\d+/);
    return {
      rank: idx + 1,
      title: titleEl?.textContent?.trim().replace(/^\d+\.\s*/, ''),
      id: match ? match[0] : null
    };
  }).filter(m => m.id);

  console.log(`Loaded ${movies.length} movies from chart/top.`);

  const queryMovie = async (movie) => {
    const variables = JSON.stringify({
      id: movie.id,
      includeUserPreferredServices: false,
      isProPage: false,
      locale: "en-US",
      location: {
        postalCodeLocation: {
          country: "US",
          postalCode: "95101"
        }
      }
    });
    const extensions = JSON.stringify({
      persistedQuery: {
        sha256Hash: "f15a4004e6e2bed83979a99e9ea57cdb89bd5eee00dacb918bdb2edad67f583c",
        version: 1
      }
    });
    const url = `https://caching.graphql.imdb.com/?operationName=TitleSummaryPromptFromBase&variables=${encodeURIComponent(variables)}&extensions=${encodeURIComponent(extensions)}`;
    try {
      const resp = await fetch(url);
      const data = await resp.json();
      const cats = data.data?.title?.watchOptionsByCategory?.categorizedWatchOptionsList || [];
      const opts = [];
      for (const cat of cats) {
        for (const o of (cat.watchOptions || [])) {
          opts.push({
            category: cat.categoryName?.value,
            providerName: o.provider?.name?.value,
            providerId: o.provider?.id,
            desc: o.description?.value,
            link: o.link
          });
        }
      }
      return {
        movie,
        opts
      };
    } catch(e) {
      return { movie, error: e.toString() };
    }
  };

  // Run in chunks of 20
  const allResults = [];
  for (let i = 0; i < movies.length; i += 20) {
    const chunk = movies.slice(i, i + 20);
    const chunkRes = await Promise.all(chunk.map(queryMovie));
    allResults.push(...chunkRes);
  }

  // Analyze all results
  const allProviders = new Set();
  const amcMovies = [];
  const streamingMovies = [];

  for (const r of allResults) {
    if (r.opts && r.opts.length > 0) {
      for (const opt of r.opts) {
        allProviders.add(`${opt.category}: ${opt.providerName} (${opt.providerId})`);
        if (opt.providerName?.toLowerCase().includes('amc') || opt.providerId?.toLowerCase().includes('amc')) {
          amcMovies.push({ movie: r.movie, opt });
        }
        if (opt.category === 'STREAMING') {
          streamingMovies.push({ movie: r.movie, opt });
        }
      }
    }
  }

  return {
    totalChecked: allResults.length,
    moviesWithOptsCount: allResults.filter(r => r.opts && r.opts.length > 0).length,
    distinctProviders: Array.from(allProviders),
    amcMovies,
    streamingMoviesCount: streamingMovies.length,
    sampleStreaming: streamingMovies.slice(0, 10)
  };
});

console.log("Total checked:", result.totalChecked);
console.log("Movies with options:", result.moviesWithOptsCount);
console.log("Distinct providers:", result.distinctProviders);
console.log("AMC movies found:", JSON.stringify(result.amcMovies, null, 2));
console.log("Streaming movies count:", result.streamingMoviesCount);
