const scanForAmc = await browserjs(tabId, async () => {
  const items = Array.from(document.querySelectorAll('.ipc-metadata-list-summary-item'));
  const movies = items.map((item, idx) => {
    const titleEl = item.querySelector('h3, .ipc-title__text');
    const linkEl = item.querySelector('a.ipc-title-link-wrapper, a[href*="/title/"]');
    const match = linkEl?.href?.match(/tt\d+/);
    return {
      rank: idx + 1,
      title: titleEl?.textContent?.trim().replace(/^\d+\.\s*/, ''),
      id: match ? match[0] : null
    };
  }).filter(m => m.id);

  const queryMovie = async (m) => {
    const variables = JSON.stringify({
      id: m.id,
      includeUserPreferredServices: false,
      isProPage: false,
      locale: "en-US",
      location: {
        postalCodeLocation: {
          country: "US",
          postalCode: "95101"
        }
      }
    });
    const extensions = JSON.stringify({
      persistedQuery: {
        sha256Hash: "f15a4004e6e2bed83979a99e9ea57cdb89bd5eee00dacb918bdb2edad67f583c",
        version: 1
      }
    });
    const url = `https://caching.graphql.imdb.com/?operationName=TitleSummaryPromptFromBase&variables=${encodeURIComponent(variables)}&extensions=${encodeURIComponent(extensions)}`;
    try {
      const resp = await fetch(url);
      const data = await resp.json();
      const cats = data.data?.title?.watchOptionsByCategory?.categorizedWatchOptionsList || [];
      const amcOpts = [];
      const allOpts = [];
      for (const c of cats) {
        const catName = c.categoryName?.value;
        for (const w of (c.watchOptions || [])) {
          const pName = w.provider?.name?.value || "";
          const pId = w.provider?.id || "";
          const optTitle = w.title?.value || "";
          allOpts.push(`${catName}: ${pName}`);
          if (pName.toLowerCase().includes('amc') || pId.toLowerCase().includes('amc') || optTitle.toLowerCase().includes('amc')) {
            amcOpts.push({
              category: catName,
              providerName: pName,
              providerId: pId,
              title: optTitle,
              desc: w.description?.value,
              link: w.link
            });
          }
        }
      }
      return { movie: m, amcOpts, allOpts };
    } catch(e) {
      return { movie: m, error: e.toString() };
    }
  };

  const matches = [];
  const checked = [];

  // Check in chunks of 25
  for (let i = 0; i < movies.length; i += 25) {
    const chunk = movies.slice(i, i + 25);
    const chunkRes = await Promise.all(chunk.map(queryMovie));
    for (const res of chunkRes) {
      if (res.amcOpts && res.amcOpts.length > 0) {
        matches.push(res);
      }
    }
    checked.push(`Checked up to rank ${Math.min(i + 25, movies.length)}: found ${matches.length}`);
    if (matches.length > 0) {
      // Return early once we have matches!
      return {
        status: "found",
        progress: checked,
        matches
      };
    }
  }

  return {
    status: "done",
    progress: checked,
    matches
  };
});

