Arguments: {"cwd":null,"code":"const tabId = 118779795;

const scanMovies = async (startIndex, count) => {
  return await browserjs(tabId, async (start, length) => {
    const items = Array.from(document.querySelectorAll('.ipc-metadata-list-summary-item'));
    const slice = items.slice(start, start + length).map((item, idx) => {
      const titleEl = item.querySelector('h3, .ipc-title__text');
      const linkEl = item.querySelector('a.ipc-title-link-wrapper, a[href*="/title/"]');
      const match = linkEl?.href?.match(/tt\d+/);
      return {
        rank: start + idx + 1,
        title: titleEl?.textContent?.trim().replace(/^\d+\.\s*/, ''),
        id: match ? match[0] : null
      };
    }).filter(m => m.id);

    const queryMovie = async (m) => {
      const variables = JSON.stringify({
        id: m.id,
        includeUserPreferredServices: false,
        isProPage: false,
        locale: "en-US",
        location: {
          postalCodeLocation: {
            country: "US",
            postalCode: "95101"
          }
        }
      });
      const extensions = JSON.stringify({
        persistedQuery: {
          sha256Hash: "f15a4004e6e2bed83979a99e9ea57cdb89bd5eee00dacb918bdb2edad67f583c",
          version: 1
        }
      });
      const url = `https://caching.graphql.imdb.com/?operationName=TitleSummaryPromptFromBase&variables=${encodeURIComponent(variables)}&extensions=${encodeURIComponent(extensions)}`;

      try {
        const resp = await fetch(url, {
          headers: {
            'content-type': 'application/json'
          }
        });
        if (!resp.ok) return { rank: m.rank, title: m.title, error: resp.status };
        const data = await resp.json();
        const cats = data.data?.title?.watchOptionsByCategory?.categorizedWatchOptionsList || [];
        const provs = [];
        let amc = null;
        for (const c of cats) {
          for (const w of (c.watchOptions || [])) {
            const name = w.provider?.name?.value || "";
            const id = w.provider?.id || "";
            provs.push(`${c.categoryName?.value}: ${name}`);
            if (name.toLowerCase().includes('amc') || id.toLowerCase().includes('amc')) {
              amc = {
                category: c.categoryName?.value,
                name,
                id,
                desc: w.description?.value,
                link: w.link
              };
            }
          }
        }
        return { rank: m.rank, title: m.title, id: m.id, provs, amc };
      } catch(e) {
        return { rank: m.rank, title: m.title, error: e.toString() };
      }
    };

    const out = [];
    for (let i = 0; i < slice.length; i += 5) {
      const sub = slice.slice(i, i + 5);
      const res = await Promise.all(sub.map(queryMovie));
      out.push(...res);
    }
    return out;
  }, startIndex, count);
};

// Let's scan in chunks of 50
for (let start = 0; start < 250; start += 50) {
  console.log(`Scanning movies ${start + 1} to ${Math.min(start + 50, 250)}...`);
  const results = await scanMovies(start, 50);
  const amcHits = results.filter(r => r.amc);
  if (amcHits.length > 0) {
    console.log("FOUND AMC+ MOVIE(S):", JSON.stringify(amcHits, null, 2));
    break;
  } else {
    console.log(`No AMC+ in ${start + 1}-${start + 50}. Sample providers:`, results.filter(r => r.provs?.length > 0).slice(0, 3).map(r => ({ title: r.title, provs: r.provs })));
  }
}
